def calculate_max_score(a):
    n = len(a)
    max_score = 0
    for i in range(n):
        current_index = i
        current_score = 0
        while current_index < n:
            current_score += a[current_index]
            current_index += a[current_index]
        max_score = max(max_score, current_score)
    return max_score

def main():
    t = int(input())
    results = []
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        results.append(calculate_max_score(a))
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
